using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a user by their identifier. This is an offline method if the current user is not a bot
    /// </summary>
    public Task<TdLib.TdApi.Objects.User> GetUserAsync(long userId = default)
    {

           using var activity =  StartCallActivity("GetUserAsync", typeof(GetUser).FullName ?? "GetUserAsync");

           try
           {
             return client.GetUserAsync(userId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
